INSERT INTO source_documents (id,project_id,repository_location_id,path,document_kind,title,byte_size,mtime_ns,last_seen_at,freshness_status) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,now(),$9) ON CONFLICT (repository_location_id,path) DO UPDATE SET project_id=EXCLUDED.project_id,document_kind=EXCLUDED.document_kind,title=EXCLUDED.title,byte_size=EXCLUDED.byte_size,mtime_ns=EXCLUDED.mtime_ns,last_seen_at=now(),is_current=true,freshness_status=EXCLUDED.freshness_status,superseded_by_document_id=NULL,duplicate_of_document_id=NULL RETURNING id
